import {
  Mesh,
  PlaneGeometry,
  Object3D,
  Vector3,
  Vector2,
  Euler,
} from 'three/webgpu';
import {
  MeshBasicNodeMaterial,
  texture,
  uv,
} from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  // ----- Load texture (cached) -----
  const imageUrl = config.assets?.imageUrl ?? '';
  const tex = ctx.textureLoader.load(imageUrl);

  // ----- Determine aspect ratio from atlas region -----
  const rect = config.atlas?.sourceRect ?? { x: 0, y: 0, width: 1, height: 1 };
  const aspect = rect.width / rect.height;

  // ----- Geometry (plane sized to aspect ratio) -----
  const geometry = new PlaneGeometry(aspect, 1, 1, 1);

  // ----- Node material with UV mapping -----
  const material = new MeshBasicNodeMaterial();
  // Full‑texture UV (region starts at 0,0 and occupies full texture in this case)
  const uvNode = uv();
  material.map = texture(tex, uvNode);

  // ----- Mesh creation -----
  const mesh = new Mesh(geometry, material);
  mesh.name = config.id ?? 'features-card-2';

  // ----- Apply transform from config -----
  if (config.position) {
    mesh.position.set(
      config.position[0],
      config.position[1],
      config.position[2]
    );
  } else {
    mesh.position.set(0, -0.3, 0);
  }

  if (config.rotation) {
    mesh.rotation.set(
      config.rotation[0],
      config.rotation[1],
      config.rotation[2]
    );
  } else {
    mesh.rotation.set(0, 0, 0);
  }

  if (config.scale) {
    mesh.scale.set(config.scale[0], config.scale[1], config.scale[2]);
  } else {
    mesh.scale.set(1, 1, 1);
  }

  // ----- Billboard toward camera -----
  mesh.onBeforeRender = function (_, __, camera) {
    // make the plane face the camera while preserving its up vector
    const pos = mesh.position;
    mesh.lookAt(
      camera.position.x,
      camera.position.y,
      camera.position.z
    );
    mesh.position.copy(pos); // undo translation caused by lookAt
  };

  // ----- Event handlers placeholder -----
  mesh.userData.handlers = {};

  // ----- Cleanup routine -----
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    // texture is managed by the texture loader cache; do not dispose here
    if (mesh.onBeforeRender) mesh.onBeforeRender = null;
    mesh.userData.handlers = null;
    // kill any GSAP timelines attached to this object (none in this node)
    gsap.killTweensOf(mesh);
  };

  return mesh;
}
